import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";
const files = execSync('git grep -l -E "<app-(status|fancy)-pill" -- src', { encoding: "utf8" }).split("\n").filter(Boolean);
const tag = /<app-(?:status|fancy)-pill(\s(?:[^>"']|"[^"]*"|'[^']*')*)/g;
let n = 0;
for (const f of files) {
  const src = readFileSync(f, "utf8");
  const out = src.replace(tag, (m, attrs) => {
    const fixed = attrs.replace(/(?<![\w.-])disableTooltip(?![\w-])/g, () => { n++; return "hideHint"; });
    return m.slice(0, m.length - attrs.length) + fixed;
  });
  if (out !== src) writeFileSync(f, out);
}
console.log("files", files.length, "attributes renamed", n);
EOF
